import {getLesson} from '../core.mjs?v=r66';
import {lessonVisualAssets} from '../lesson-visuals.mjs?v=r66';
import {workerRequest} from '../services/worker-client.mjs?v=r66';

export function createOfflineController({LESSONS,curriculum,CURRICULA,store,readObj,t,main,notify,render,version,getOffline,setOffline,request=workerRequest}){
const KEY=curriculum.storageKey,VERSION=version;let offline=getOffline();
const saveOffline=value=>{const ok=store.set(KEY+'-offline',value);setOffline(value);return ok;};
const offlineChecks=new Map();
function offlineControls(l){const state=offlineChecks.get(l.id),ready=state==='ready',busy=state==='checking'||state?.startsWith('progress:');let message=ready?t('✓ पृष्ठ जाँचे गए · बिना इंटरनेट उपलब्ध','✓ Pages checked · available offline'):state==='checking'?t('सहेजे पृष्ठ जाँच रहे हैं…','Checking stored pages…'):state?.startsWith('progress:')?t('पृष्ठ रख रहे हैं: ','Storing pages: ')+state.slice(9):state==='storage'?t('उपकरण में जगह कम है। जगह बनाकर फिर प्रयास करें।','Device storage is full. Free space and retry.'):state==='changed'?t('पृष्ठ बदल गया है। इंटरनेट के साथ फिर खोलें।','A page has changed. Reopen with internet access.'):state==='missing'?t('कुछ पृष्ठ उपलब्ध नहीं हैं। फिर से रखें।','Some pages are missing. Store them again.'):state?t('पृष्ठ नहीं रख पाए। इंटरनेट जाँचकर फिर प्रयास करें।','Could not store pages. Check your connection and retry.'):t('इस पाठ और जुड़े कार्यपत्रकों को इसी ब्राउज़र में रखें।','Store this lesson and its linked worksheets in this browser.');return `<button class="tool-button" data-offline="${l.id}" ${busy?'disabled':''}>${ready?t('पृष्ठ फिर जाँचें','Check pages again'):t('बिना इंटरनेट के लिए रखें','Keep for offline use')}</button>${offline[l.id]?`<button class="text-button" data-remove-offline="${l.id}">${t('ऑफलाइन प्रति हटाएँ','Remove offline copy')}</button>`:''}<p role="status" class="small">${message}</p>`;}
function refreshOffline(id){for(const el of main.querySelectorAll('[data-offline-controls]'))if(el.dataset.offlineControls===id)el.innerHTML=offlineControls(getLesson(LESSONS,id));}
async function checkOffline(id){if(offlineChecks.has(id))return;offlineChecks.set(id,'checking');refreshOffline(id);try{await request('CHECK_LESSON',lessonVisualAssets(getLesson(LESSONS,id),curriculum.visualStyle));offlineChecks.set(id,'ready');}catch(error){offlineChecks.set(id,error.message);}refreshOffline(id);}
async function keepOffline(id){const l=getLesson(LESSONS,id);if(!l)return;offlineChecks.set(id,'progress:0');refreshOffline(id);try{await request('CACHE_LESSON',lessonVisualAssets(l,curriculum.visualStyle),{progress:true},data=>{offlineChecks.set(id,`progress:${data.progress}/${data.total}`);refreshOffline(id);});offline=readObj('-offline');offline[id]=VERSION;const persisted=saveOffline(offline);offlineChecks.delete(id);await checkOffline(id);notify(persisted?t('पाठ बिना इंटरनेट के लिए तैयार है।','Lesson is ready for offline use.'):t('पृष्ठ रखे गए; सूची केवल इस सत्र तक याद रहेगी।','Pages stored; this list will only be remembered for this session.'));}catch(error){offlineChecks.set(id,error.message);refreshOffline(id);}}
async function removeOffline(id){const l=getLesson(LESSONS,id);const keep=CURRICULA.flatMap(pack=>{const saved=store.get(pack.storageKey+'-offline',{});return pack.lessons.filter(item=>saved?.[item.id]&&!(pack.id===curriculum.id&&item.id===id)).flatMap(item=>lessonVisualAssets(item,pack.visualStyle));});try{await request('REMOVE_LESSON',lessonVisualAssets(l,curriculum.visualStyle),{keep});offline=readObj('-offline');delete offline[id];saveOffline(offline);offlineChecks.delete(id);render();notify(t('ऑफलाइन प्रति हटी। नोट और मेरी सूची सुरक्षित हैं।','Offline copy removed. Notes and your list are unchanged.'));}catch{notify(t('प्रति नहीं हटी। फिर प्रयास करें।','Could not remove copy. Retry.'));}}

function reset(){offlineChecks.clear();for(const el of main.querySelectorAll('[data-offline-controls]'))if(offline[el.dataset.offlineControls])checkOffline(el.dataset.offlineControls);}
return {offlineControls,checkOffline,keepOffline,removeOffline,reset};
}
